public class ExamScoreBandCounter { static int countInBand(int[] scores,int low,int high){return firstGreater(scores,high)-firstGreater(scores,low-1);} static int firstGreater(int[] a,int value){int left=0,right=a.length;while(left<right){int mid=(left+right)/2;if(a[mid]<=value)left=mid+1;else right=mid;}return left;} public static void main(String[]args){int[] scores={35,42,42,50,58,58,58,63,71,88};System.out.println(countInBand(scores,42,58));} }
